from pathlib import Path
from PIL import Image,ImageDraw
import json,hashlib
R=Path(__file__).resolve().parent;sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
N=['yawn-hand-release-v1','yawn-lift-v1','yawn-near-v1','yawn-cover-v1','rest-middle-v1','rest-settled-v2','drowsy-middle-v1','doze-v1','wake-middle-v1','wake-alert-v1','hover-middle-v1','hover-attend-v1','tap-response-v1']
def path(n):return 'references/closed-rest-rigid-v2.png' if n=='closed' else 'frames/'+n+'.png'
def pose(n):return 'upright-v2:closed' if n=='closed' else 'upright-v2:companionship:'+n
stable={'closed','rest-settled-v2','doze-v1','hover-attend-v1'}
def fr(n,ms,phase,cue):return {'source':path(n),'sha256':sha(R/path(n)),'durationMs':ms,'pose':pose(n),'phase':phase,'cue':cue,'pauseSafe':n in stable,'exitTo':[pose(n)] if n in stable else []}
def seq(id,action,entry,exit,rows,kind='bridge',loop=None):return {'id':id,'action':action,'kind':kind,'geometryReference':'varin-upright-v2','canvas':[512,512],'entryPose':pose(entry),'exitPose':pose(exit),'loop':loop,'frames':[fr(*x) for x in rows]}
enter=[('closed',80,'enter','REST_NOTICE'),('yawn-hand-release-v1',80,'enter','YAWN_RELEASE_CONTACT'),('yawn-lift-v1',100,'act','YAWN_RAISE'),('yawn-near-v1',90,'act','YAWN_NEAR'),('yawn-cover-v1',620,'act','YAWN_COVER'),('yawn-near-v1',100,'exit','YAWN_LOWER'),('yawn-lift-v1',110,'exit','YAWN_LOWER'),('yawn-hand-release-v1',100,'exit','YAWN_CONTACT_RETURN'),('closed',280,'hold','SUPPORTED_REST'),('rest-middle-v1',140,'enter','REST_HAND_RELEASE'),('rest-settled-v2',900,'hold','REST_SETTLED'),('drowsy-middle-v1',450,'enter','DROWSY'),('doze-v1',240,'hold','DOZE')]
wake=[('doze-v1',40,'enter','WAKE_NOTICE'),('wake-middle-v1',130,'enter','WAKE_REFOCUS'),('wake-alert-v1',240,'act','WAKE_ALERT'),('rest-settled-v2',110,'exit','WAKE_SETTLE'),('rest-middle-v1',120,'exit','HAND_RETURN'),('closed',100,'exit','CLOSED_READY')]
hover=[('closed',40,'enter','HOVER_NOTICE'),('hover-middle-v1',100,'enter','ATTEND_ENTER'),('hover-attend-v1',650,'hold','LOCAL_ATTEND'),('hover-middle-v1',110,'exit','ATTEND_RELEASE'),('closed',100,'exit','CLOSED_READY')]
tap=[('closed',40,'enter','TAP_NOTICE'),('hover-middle-v1',90,'enter','ATTEND_ENTER'),('hover-attend-v1',90,'act','LOCAL_ATTEND'),('tap-response-v1',210,'act','LOCAL_TAP_SMILE'),('hover-attend-v1',90,'exit','TAP_RELEASE'),('hover-middle-v1',100,'exit','ATTEND_RELEASE'),('closed',100,'exit','CLOSED_READY')]
sequences=[seq('companionship-rest-enter','rest-sleep','closed','doze-v1',enter),seq('companionship-doze-hold','rest-sleep','doze-v1','doze-v1',[('doze-v1',1000,'hold','DOZE')],kind='action',loop=[0,1]),seq('companionship-wake-exit','rest-sleep','doze-v1','closed',wake),seq('companionship-hover-response','hover-response','closed','closed',hover,kind='action'),seq('companionship-closed-tap','tap-response','closed','closed',tap,kind='action'),seq('companionship-hover-to-tap','tap-response','hover-attend-v1','closed',tap[3:],kind='bridge')]
relax=enter[:11]+[('rest-middle-v1',120,'exit','HAND_RETURN'),('closed',100,'exit','CLOSED_READY')]
sequences.append(seq('companionship-relax-idle-once','relax-idle','closed','closed',relax,kind='action'))
for item in sequences:item['publicAction']=item['action']
# first exposure of hover-to-tap must be actual entry drawing, not the tap peak.
next(x for x in sequences if x['id']=='companionship-hover-to-tap')['frames'].insert(0,fr('hover-attend-v1',30,'enter','TAP_NOTICE'))
recover={'closed':[], 'yawn-hand-release-v1':['closed'],'yawn-lift-v1':['yawn-hand-release-v1','closed'],'yawn-near-v1':['yawn-lift-v1','yawn-hand-release-v1','closed'],'yawn-cover-v1':['yawn-near-v1','yawn-lift-v1','yawn-hand-release-v1','closed'],'rest-middle-v1':['closed'],'rest-settled-v2':['rest-middle-v1','closed'],'drowsy-middle-v1':['wake-middle-v1','wake-alert-v1','rest-settled-v2','rest-middle-v1','closed'],'doze-v1':['wake-middle-v1','wake-alert-v1','rest-settled-v2','rest-middle-v1','closed'],'wake-middle-v1':['wake-alert-v1','rest-settled-v2','rest-middle-v1','closed'],'wake-alert-v1':['rest-settled-v2','rest-middle-v1','closed'],'hover-middle-v1':['closed'],'hover-attend-v1':['hover-middle-v1','closed'],'tap-response-v1':['hover-attend-v1','hover-middle-v1','closed']}
recovery=[]
for n,route in recover.items():
 recovery.append({'actualSourceSHA256':sha(R/path(n)),'actualPose':pose(n),'targetPose':'upright-v2:closed','currentExposureMaximumRemainingMs':0 if n in stable else 40,'frames':[fr(p,85 if p!='closed' else 60,'exit','SAFE_RECOVER') for p in route],'factRule':'Update latest intent/Host UI immediately; this drawing-only recovery never delays pointer-root translation or implies approval/completion.'})
records=[]
for n in N:
 p=json.loads((R/'frames'/f'{n}-provenance.json').read_text());p.update({'pose':pose(n),'embeddedStool':True,'phaseRoles':sorted({f['phase'] for s in sequences for f in s['frames'] if f['source']==path(n)}),'pauseSafe':n in stable});records.append(p)
manifest={'status':'authored candidates; first rest direction approved; full sequence and runtime review pending','geometryReference':'varin-upright-v2','canvas':[512,512],'runtimeSourceNames':N,'newUniqueSourceCount':len(N),'sourceRoot':'.','sequences':sequences,'safeRecoveryByActualSource':recovery,'sourceRecords':records,'localEligibility':{'rest-sleep':'only continuous clear inactive >=~5min, no active work, pending ask/permission, unknown connection, menu/drag; visible only; hidden resets, never catch-up play','wake':'fresh local input/new task/error/permission/unknown excludes rest immediately; use actual drawing recovery; never changes OS sleep or Host status','hover-response':'actual character alpha-hitmask residency ~700ms; 10s cooldown; leave recovers; transparent padding/global cursor ignored; closed endpoint only','tap-response':'actual local tap only, no double-click semantics, no task approval or completion; no forced computer close; existing v2 open tap remains in use','yawn':'once in rest entry, not a repeating hold action','reducedMotion':'suppress optional rest/hover recurrence; keep canonical closed and necessary current-pose return'},'acceptedSourceBoundary':'No v2 source overwritten. Normalized-reference PNGs are processing references and never runtime sources.','anatomicalNote':'Yawn uses character RIGHT/image-LEFT hand. Image-right hand remains on closed laptop. After yawn returns, image-right hand can rest on own skirt; not stool.','ordinaryActionGroups':{'rest-sleep':{'enter':'companionship-rest-enter','hold':'companionship-doze-hold','exit':'companionship-wake-exit'},'hover-response':{'oneShot':'companionship-hover-response'},'tap-response':{'closed':'companionship-closed-tap','fromHover':'companionship-hover-to-tap','open':'reuse existing v2 open tap, no v3 substitution'}}}
manifest['ordinaryActionGroups']['relax-idle']={'oneShot':'companionship-relax-idle-once','condition':'clear inactive only, low-frequency local rest; never a repeated yawn loop'}
manifest['ordinaryActionGroups']['idle-closed']={'implementation':'keep selected v2 closed-idle unchanged; do not replace ordinary quiet with sleep'}
manifest['localEligibility']['wakeReset']='Any fresh input, tap, hover attention wake or new task clears continuous-idle eligibility; runtime must not return to sleep on the next frame.'
(R/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
# Three explicit QA exposure studies. A 1.5s doze stand-in is only a preview, not auto-wake logic.
studies={'rest-full':enter+[('doze-v1',1500,'hold','DOZE_PREVIEW_ONLY')]+wake,'hover':hover,'tap':tap}
for name,rows in studies.items():
 imgs=[]
 for n,*_ in rows:
  b=Image.new('RGBA',(512,512),'#e9eef2');b.alpha_composite(Image.open(R/path(n)));imgs.append(b.convert('RGB'))
 imgs[0].save(R/'qa'/f'{name}-normal-timing.gif',save_all=True,append_images=imgs[1:],duration=[x[1] for x in rows],loop=0)
 (R/'qa'/f'{name}-preview-timing.json').write_text(json.dumps({'notRuntime':'finite preview only; real sleep hold wakes only on new eligibility/input facts','frames':[fr(*x) for x in rows]},indent=2)+'\n')
rejected={'raw':'raw/rest-settled-v1.png','sha256':sha(R/'raw/rest-settled-v1.png'),'status':'rejected','reason':'Hand contacted stool instead of own skirt, violating intended simple rest support. Corrected v2 replaces it; not a reachable source.'};(R/'rejected-source.json').write_text(json.dumps(rejected,indent=2)+'\n')
